class SimpleQueue<T>
{
    private readonly Queue<T> _items = new();
    private readonly object _gate = new();

    public void Put(T item)
    {
        lock (_gate)
        {
            _items.Enqueue(item);
            Monitor.Pulse(_gate);        // разбудить одного ждущего
        }
    }

    public T Take()
    {
        lock (_gate)
        {
            while (_items.Count == 0)
                Monitor.Wait(_gate);     // отпустить замок и уснуть
            return _items.Dequeue();
        }
    }
}

